design_artifacts.class_diagram_mermaid:
```mermaid
classDiagram
    class Calculator {
        +run()
        -display_prompt()
        -process_input(input: str)
    }
    class ExpressionParser {
        +parse(expression: str)~List~Token~~
        -tokenize(expression: str)~List~Token~~
        -validate(tokens: List~Token~)
    }
    class Evaluator {
        +evaluate(tokens: List~Token~)~float~
        -apply_operator(op: Token, left: float, right: float)~float~
        -get_precedence(op: str)~int~
    }
    class Token {
        +type: TokenType
        +value: str
    }
    class TokenType {
        <<enumeration>>
        NUMBER
        PLUS
        MINUS
        MULTIPLY
        DIVIDE
        LPAREN
        RPAREN
    }
    class CalculatorException {
        +message: str
    }
    class DivisionByZeroException {
    }
    class InvalidExpressionException {
    }
    Calculator --> ExpressionParser
    Calculator --> Evaluator
    ExpressionParser --> Token
    Evaluator --> Token
    CalculatorException <|-- DivisionByZeroException
    CalculatorException <|-- InvalidExpressionException
```
